def main():
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "remaining_hebrew_quests.json")
    json.dump(Q, open(out, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print(f"wrote remaining_hebrew_quests.json: {len(Q)} quest paragraphs")
    bad = [g for g, v in Q.items() if not re.search(r"[א-ת]", v)]
    ub = [g for g, v in Q.items() if v.count("<b>") != v.count("</b>")]
    print("no-hebrew:", bad, " unbalanced <b>:", ub)


if __name__ == "__main__":
    main()
